-- Current Prism schema baseline for new databases.
-- Existing installations must apply every legacy migration through
-- 20260718_120000_add_conversation_turn_context_mode.sql, then run `prism migrate adopt`.

CREATE TABLE IF NOT EXISTS `users` (`id` bigint unsigned AUTO_INCREMENT COMMENT '主键ID',`created_at` datetime(3) NULL COMMENT '创建时间',`updated_at` datetime(3) NULL COMMENT '更新时间',`deleted_at` datetime(3) NULL COMMENT '删除时间',`username` varchar(50) NOT NULL COMMENT '用户名',`password` varchar(100) NOT NULL COMMENT '密码(加密)',`role` varchar(10) DEFAULT 'user' COMMENT '角色(admin/user)',`balance` decimal(20,8) NOT NULL DEFAULT '0' COMMENT '账户余额',`status` tinyint DEFAULT 1 COMMENT '状态(1启用/0禁用)',`session_version` bigint unsigned NOT NULL DEFAULT 0 COMMENT '控制台会话版本',PRIMARY KEY (`id`),INDEX `idx_users_created_at` (`created_at`),INDEX `idx_users_deleted_at` (`deleted_at`),UNIQUE INDEX `idx_users_username` (`username`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `tokens` (`id` bigint unsigned AUTO_INCREMENT COMMENT '主键ID',`created_at` datetime(3) NULL COMMENT '创建时间',`updated_at` datetime(3) NULL COMMENT '更新时间',`deleted_at` datetime(3) NULL COMMENT '删除时间',`user_id` bigint unsigned DEFAULT 0 COMMENT '用户ID',`key` varchar(64) NOT NULL COMMENT 'API密钥(hash)',`key_hint` varchar(20) COMMENT '密钥提示(后四位)',`name` varchar(50) COMMENT '令牌名称',`balance` decimal(20,8) NOT NULL DEFAULT '0' COMMENT '剩余额度',`total_used` decimal(20,8) NOT NULL DEFAULT '0' COMMENT '已使用额度',`rate_limit` bigint DEFAULT 60 COMMENT '速率限制(次/分钟)',`status` tinyint DEFAULT 1 COMMENT '状态(1启用/0禁用)',PRIMARY KEY (`id`),INDEX `idx_tokens_created_at` (`created_at`),INDEX `idx_tokens_deleted_at` (`deleted_at`),INDEX `idx_tokens_user_id` (`user_id`),UNIQUE INDEX `idx_tokens_key` (`key`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `channels` (`id` bigint unsigned AUTO_INCREMENT COMMENT '主键ID',`created_at` datetime(3) NULL COMMENT '创建时间',`updated_at` datetime(3) NULL COMMENT '更新时间',`deleted_at` datetime(3) NULL COMMENT '删除时间',`type` varchar(20) NOT NULL COMMENT '渠道类型标识',`name` varchar(50) COMMENT '渠道名称',`base_url` varchar(255) COMMENT '基础URL',`callback_secret` varchar(128) COMMENT '回调签名密钥',`config` JSON COMMENT '渠道配置(JSON)',`status` tinyint DEFAULT 1 COMMENT '状态(1启用/0禁用)',`sort` bigint DEFAULT 0 COMMENT '排序(降序)',PRIMARY KEY (`id`),INDEX `idx_channels_created_at` (`created_at`),INDEX `idx_channels_deleted_at` (`deleted_at`),UNIQUE INDEX `idx_channels_type` (`type`),INDEX `idx_channels_sort` (`sort`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `channel_accounts` (`id` bigint unsigned AUTO_INCREMENT COMMENT '主键ID',`created_at` datetime(3) NULL COMMENT '创建时间',`updated_at` datetime(3) NULL COMMENT '更新时间',`deleted_at` datetime(3) NULL COMMENT '删除时间',`channel_id` bigint unsigned NOT NULL COMMENT '所属渠道ID',`name` varchar(50) COMMENT '账号名称',`api_key` text COMMENT 'API密钥',`config` JSON COMMENT '账号配置(JSON)',`weight` bigint DEFAULT 10 COMMENT '负载均衡权重',`status` tinyint DEFAULT 1 COMMENT '状态(1启用/0禁用)',`max_tasks` bigint DEFAULT 0 COMMENT '最大并发任务数(0=不限制)',`current_tasks` bigint DEFAULT 0 COMMENT '当前任务数',`supported_models` JSON COMMENT '支持的模型列表(空=全部)',PRIMARY KEY (`id`),INDEX `idx_channel_accounts_created_at` (`created_at`),INDEX `idx_channel_accounts_deleted_at` (`deleted_at`),INDEX `idx_channel_accounts_channel_id` (`channel_id`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `models` (`code` varchar(80) COMMENT '模型标识',`name` varchar(100) NOT NULL COMMENT '显示名称',`type` varchar(20) NOT NULL DEFAULT 'chat' COMMENT '模型类型',`provider` varchar(30) DEFAULT '' COMMENT '来源标识',`protocol` varchar(20) DEFAULT 'openai' COMMENT '协议类型(chat虚拟端点用)',`description` varchar(500) DEFAULT '' COMMENT '模型描述',`features` JSON COMMENT '能力标签',`param_schema` JSON COMMENT '参数schema',`max_tokens` bigint DEFAULT 0 COMMENT '最大token数',`thinking_config` JSON COMMENT '思考模式配置(档位/默认/锁定)',`sort` bigint DEFAULT 0 COMMENT '排序(降序)',`status` tinyint DEFAULT 1 COMMENT '状态(1启用/0禁用)',`created_at` datetime(3) NULL COMMENT '创建时间',`updated_at` datetime(3) NULL COMMENT '更新时间',`deleted_at` datetime(3) NULL COMMENT '删除时间',PRIMARY KEY (`code`),INDEX `idx_models_sort` (`sort`),INDEX `idx_models_created_at` (`created_at`),INDEX `idx_models_deleted_at` (`deleted_at`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `endpoints` (`id` bigint unsigned AUTO_INCREMENT COMMENT '主键ID',`created_at` datetime(3) NULL COMMENT '创建时间',`updated_at` datetime(3) NULL COMMENT '更新时间',`deleted_at` datetime(3) NULL COMMENT '删除时间',`model_code` varchar(80) NOT NULL COMMENT '模型标识',`channel_id` bigint unsigned NOT NULL COMMENT '渠道ID',`account_id` bigint unsigned DEFAULT 0 COMMENT '所属账号(key)ID,0=渠道级兼容',`protocol` varchar(20) NOT NULL DEFAULT 'openai' COMMENT '协议类型',`request_path` varchar(255) NOT NULL DEFAULT '/v1/chat/completions' COMMENT '请求路径',`request_method` varchar(10) NOT NULL DEFAULT 'POST' COMMENT '请求方法',`content_type` varchar(50) DEFAULT 'application/json' COMMENT '内容类型',`auth_location` varchar(10) DEFAULT 'header' COMMENT '认证位置',`auth_key` varchar(50) DEFAULT 'Authorization' COMMENT '认证参数名',`auth_value_prefix` varchar(30) DEFAULT 'Bearer ' COMMENT '认证值前缀',`vendor_model` varchar(80) NOT NULL COMMENT '上游模型名',`interaction_mode` varchar(10) NOT NULL DEFAULT 'stream' COMMENT '交互模式',`supports_stream` boolean DEFAULT true COMMENT '是否支持流式',`default_stream` boolean DEFAULT true COMMENT '默认使用流式',`price_mode` varchar(10) DEFAULT 'token' COMMENT '计价模式',`input_price` decimal(12,8) DEFAULT '0' COMMENT '输入价格',`output_price` decimal(12,8) DEFAULT '0' COMMENT '输出价格',`param_mapping` JSON COMMENT '参数映射',`param_schema` JSON COMMENT '端点参数schema(覆盖模型级)',`response_mapping` JSON COMMENT '响应映射',`poll_path` varchar(255) DEFAULT '' COMMENT '轮询路径',`poll_method` varchar(10) DEFAULT 'GET' COMMENT '轮询方法',`poll_interval` bigint DEFAULT 5 COMMENT '轮询间隔秒',`poll_max_attempts` bigint DEFAULT 60 COMMENT '最大轮询次数',`poll_param_mapping` JSON COMMENT '轮询参数映射',`poll_response_mapping` JSON COMMENT '轮询响应映射',`callback_mapping` JSON COMMENT '回调映射',`extra_headers` JSON COMMENT '额外请求头',`extra_config` JSON COMMENT '扩展配置',`timeout` bigint DEFAULT 120 COMMENT '超时秒',`priority` bigint DEFAULT 0 COMMENT '优先级',`status` tinyint DEFAULT 1 COMMENT '状态',PRIMARY KEY (`id`),INDEX `idx_endpoints_created_at` (`created_at`),INDEX `idx_endpoints_deleted_at` (`deleted_at`),INDEX `idx_endpoints_model_code` (`model_code`),INDEX `idx_endpoints_channel_id` (`channel_id`),INDEX `idx_endpoints_account_id` (`account_id`),CONSTRAINT `fk_endpoints_model` FOREIGN KEY (`model_code`) REFERENCES `models`(`code`),CONSTRAINT `fk_endpoints_channel` FOREIGN KEY (`channel_id`) REFERENCES `channels`(`id`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `tasks` (`id` bigint unsigned AUTO_INCREMENT COMMENT '主键ID',`created_at` datetime(3) NULL COMMENT '创建时间',`updated_at` datetime(3) NULL COMMENT '更新时间',`deleted_at` datetime(3) NULL COMMENT '删除时间',`task_no` varchar(32) NOT NULL COMMENT '任务编号',`call_id` varchar(64) NOT NULL DEFAULT '' COMMENT '关联调用ID',`user_id` bigint unsigned COMMENT '用户ID',`token_id` bigint unsigned COMMENT '令牌ID',`model_code` varchar(80) COMMENT '模型标识',`channel_id` bigint unsigned COMMENT '渠道ID',`endpoint_id` bigint unsigned COMMENT '端点配置ID',`account_id` bigint unsigned COMMENT '渠道账号ID',`vendor_task_id` varchar(100) COMMENT '供应商任务ID',`status` varchar(20) DEFAULT 'pending' COMMENT '任务状态',`progress` bigint DEFAULT 0 COMMENT '进度(0-100)',`callback_url` varchar(500) COMMENT '回调地址',`callback_status` varchar(20) COMMENT '回调状态',`callback_attempts` bigint DEFAULT 0 COMMENT '回调尝试次数',`request_params` JSON COMMENT '原始请求参数',`mapped_params` JSON COMMENT '映射后参数',`submit_checkpoint` JSON COMMENT '上游提交恢复检查点',`vendor_response` JSON COMMENT '供应商原始响应',`result` JSON COMMENT '统一结果',`error_message` text COMMENT '错误信息',`cost` decimal(20,8) NOT NULL DEFAULT '0' COMMENT '费用',`refunded` boolean DEFAULT false COMMENT '是否已退款',`account_slot_released` boolean DEFAULT false COMMENT '账号并发槽位是否已释放',`worker_lease_owner` varchar(64) NOT NULL DEFAULT '' COMMENT '任务执行租约所有者',`worker_lease_stage` varchar(24) NOT NULL DEFAULT '' COMMENT '任务执行租约阶段',`worker_lease_expires_at` datetime(3) NULL COMMENT '任务执行租约过期时间',`poll_cursor` bigint NOT NULL DEFAULT 0 COMMENT '下一轮轮询序号',`started_at` datetime(3) NULL COMMENT '开始时间',`completed_at` datetime(3) NULL COMMENT '完成时间',PRIMARY KEY (`id`),INDEX `idx_tasks_created_at` (`created_at`),INDEX `idx_tasks_deleted_at` (`deleted_at`),UNIQUE INDEX `idx_tasks_task_no` (`task_no`),INDEX `idx_tasks_call_id` (`call_id`),INDEX `idx_tasks_user_id` (`user_id`),INDEX `idx_tasks_token_id` (`token_id`),INDEX `idx_tasks_model_code` (`model_code`),INDEX `idx_tasks_channel_id` (`channel_id`),INDEX `idx_tasks_vendor_task_id` (`vendor_task_id`),INDEX `idx_tasks_status` (`status`),INDEX `idx_tasks_worker_lease_expires_at` (`worker_lease_expires_at`),CONSTRAINT `fk_tasks_channel` FOREIGN KEY (`channel_id`) REFERENCES `channels`(`id`),CONSTRAINT `fk_tasks_endpoint` FOREIGN KEY (`endpoint_id`) REFERENCES `endpoints`(`id`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `channel_request_logs` (`id` bigint unsigned AUTO_INCREMENT COMMENT '主键ID',`created_at` datetime(3) NULL COMMENT '创建时间',`updated_at` datetime(3) NULL COMMENT '更新时间',`deleted_at` datetime(3) NULL COMMENT '删除时间',`call_id` varchar(64) NOT NULL DEFAULT '',`attempt_id` bigint unsigned NOT NULL DEFAULT 0,`task_id` bigint unsigned COMMENT '关联任务ID',`task_no` varchar(32) COMMENT '任务编号',`conversation_id` bigint unsigned COMMENT '关联对话ID(Chat)',`channel_id` bigint unsigned COMMENT '渠道ID',`account_id` bigint unsigned COMMENT '渠道账号ID',`capability_code` varchar(50) COMMENT '能力编码或模型编码',`request_type` varchar(20) COMMENT '请求类型',`is_stream` boolean DEFAULT false COMMENT '是否流式请求',`model_code` varchar(80) COMMENT '请求模型',`vendor_model` varchar(100) COMMENT '供应商模型',`upstream_transport` varchar(64) NOT NULL DEFAULT '' COMMENT '实际上游传输协议',`request_path` varchar(255) COMMENT '实际上游请求路径',`finish_reason` varchar(50) COMMENT '完成原因',`response_preview` text COMMENT '响应摘要',`usage_prompt_tokens` bigint DEFAULT 0 COMMENT '输入token摘要',`usage_completion_tokens` bigint DEFAULT 0 COMMENT '输出token摘要',`usage_total_tokens` bigint DEFAULT 0 COMMENT '总token摘要',`method` varchar(10) COMMENT '请求方法',`url` varchar(500) COMMENT '请求URL',`request_headers` text COMMENT '请求头(JSON)',`request_body` mediumtext COMMENT '请求体',`status_code` bigint COMMENT 'HTTP状态码',`response_body` mediumtext COMMENT '响应体',`duration_ms` bigint COMMENT '耗时(毫秒)',`error_message` text COMMENT '错误信息',`request_at` datetime(3) NULL COMMENT '请求时间',PRIMARY KEY (`id`),INDEX `idx_channel_request_logs_created_at` (`created_at`),INDEX `idx_channel_request_logs_deleted_at` (`deleted_at`),INDEX `idx_channel_request_logs_call_id` (`call_id`),INDEX `idx_channel_request_logs_attempt_id` (`attempt_id`),INDEX `idx_channel_request_logs_task_id` (`task_id`),INDEX `idx_channel_request_logs_task_no` (`task_no`),INDEX `idx_channel_request_logs_conversation_id` (`conversation_id`),INDEX `idx_channel_request_logs_channel_id` (`channel_id`),INDEX `idx_channel_request_at` (`channel_id`,`request_at`),INDEX `idx_channel_request_logs_capability_code` (`capability_code`),INDEX `idx_capability_request_at` (`capability_code`,`request_at`),INDEX `idx_channel_request_logs_request_type` (`request_type`),INDEX `idx_channel_request_logs_upstream_transport` (`upstream_transport`),INDEX `idx_channel_request_logs_request_at` (`request_at`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `token_channel_priorities` (`id` bigint unsigned AUTO_INCREMENT COMMENT '主键ID',`created_at` datetime(3) NULL COMMENT '创建时间',`updated_at` datetime(3) NULL COMMENT '更新时间',`deleted_at` datetime(3) NULL COMMENT '删除时间',`token_id` bigint unsigned NOT NULL COMMENT '令牌ID',`capability_code` varchar(30) NOT NULL COMMENT '能力编码',`channel_id` bigint unsigned NOT NULL COMMENT '渠道ID',`priority` bigint DEFAULT 1 COMMENT '优先级(1最高)',PRIMARY KEY (`id`),INDEX `idx_token_channel_priorities_created_at` (`created_at`),INDEX `idx_token_channel_priorities_deleted_at` (`deleted_at`),INDEX `idx_token_capability` (`token_id`,`capability_code`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `conversations` (`id` bigint unsigned AUTO_INCREMENT COMMENT '主键ID',`created_at` datetime(3) NULL COMMENT '创建时间',`updated_at` datetime(3) NULL COMMENT '更新时间',`deleted_at` datetime(3) NULL COMMENT '删除时间',`user_id` bigint unsigned NOT NULL COMMENT '用户ID',`token_id` bigint unsigned NOT NULL COMMENT 'Token ID',`call_id` varchar(64) NOT NULL DEFAULT '' COMMENT '最近关联调用ID',`title` varchar(200) COMMENT '对话标题',`model` varchar(80) COMMENT '最后使用模型',`system_prompt` longtext COMMENT '系统提示词',`last_request_log_id` bigint unsigned DEFAULT 0 COMMENT '最近一次请求日志ID',`last_status` varchar(20) COMMENT '最近一次请求状态',`provider_response_id` varchar(128) DEFAULT '' COMMENT '上游有状态对话ID(如火山response_id)',`provider_key_id` bigint unsigned NOT NULL DEFAULT 0 COMMENT '上游状态所属网关Key',`upstream_transport` varchar(64) NOT NULL DEFAULT '' COMMENT '上游状态所属Transport',`total_tokens` bigint DEFAULT 0 COMMENT '累计token',`message_count` bigint DEFAULT 0 COMMENT '消息数量',`canonical_item_count` bigint unsigned NOT NULL DEFAULT 0 COMMENT '可匹配 canonical 项数',`canonical_bytes` bigint unsigned NOT NULL DEFAULT 0 COMMENT '已完成 canonical 正文字节数',`canonical_match_hash` char(64) NOT NULL DEFAULT '' COMMENT '已完成 canonical 滚动匹配哈希',`canonical_state_version` tinyint unsigned NOT NULL DEFAULT 0 COMMENT 'canonical 匹配状态版本',`turn_sequence` bigint unsigned NOT NULL DEFAULT 0 COMMENT '最后分配的轮次序号',`status` tinyint DEFAULT 1 COMMENT '状态(1启用/0禁用)',PRIMARY KEY (`id`),INDEX `idx_conversations_canonical_match` (`user_id`,`token_id`,`status`,`updated_at`,`id`),INDEX `idx_conversations_created_at` (`created_at`),INDEX `idx_conversations_deleted_at` (`deleted_at`),INDEX `idx_conversations_user_id` (`user_id`),INDEX `idx_conversations_token_id` (`token_id`),INDEX `idx_conversations_call_id` (`call_id`),INDEX `idx_conversations_last_request_log_id` (`last_request_log_id`),INDEX `idx_conversations_provider_response_id` (`provider_response_id`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `messages` (`id` bigint unsigned AUTO_INCREMENT COMMENT '主键ID',`conversation_id` bigint unsigned NOT NULL COMMENT '对话ID',`call_id` varchar(64) NOT NULL DEFAULT '' COMMENT '关联调用ID',`request_log_id` bigint unsigned DEFAULT 0 COMMENT '关联请求日志ID',`role` varchar(20) NOT NULL COMMENT '角色',`content` mediumtext NOT NULL COMMENT '内容',`attachments` mediumtext COMMENT '多模态附件(JSON)',`reasoning_content` mediumtext COMMENT '思考/推理内容',`finish_reason` varchar(50) COMMENT '完成原因',`input_tokens` bigint DEFAULT 0 COMMENT '输入token',`output_tokens` bigint DEFAULT 0 COMMENT '输出token',`model` varchar(50) COMMENT '使用模型',`channel_id` bigint unsigned DEFAULT 0 COMMENT '渠道ID',`account_id` bigint unsigned DEFAULT 0 COMMENT '账号ID',`latency_ms` bigint DEFAULT 0 COMMENT '耗时毫秒',`cost` decimal(20,8) NOT NULL DEFAULT '0' COMMENT '费用',`created_at` datetime(3) NULL COMMENT '创建时间',PRIMARY KEY (`id`),INDEX `idx_conversation_created` (`conversation_id`,`created_at`),INDEX `idx_messages_call_id` (`call_id`),INDEX `idx_messages_request_log_id` (`request_log_id`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `conversation_turns` (`id` bigint unsigned AUTO_INCREMENT,`conversation_id` bigint unsigned NOT NULL,`turn_sequence` bigint unsigned NOT NULL,`call_id` varchar(64) NOT NULL,`request_log_id` bigint unsigned NOT NULL DEFAULT 0,`model` varchar(80) NOT NULL DEFAULT '',`provider_response_id` varchar(128) NOT NULL DEFAULT '',`status` varchar(24) NOT NULL DEFAULT 'completed',`context_mode` varchar(24) NOT NULL DEFAULT 'legacy',`input_tokens` bigint NOT NULL DEFAULT 0,`output_tokens` bigint NOT NULL DEFAULT 0,`total_tokens` bigint NOT NULL DEFAULT 0,`cost` decimal(20,8) NOT NULL DEFAULT '0',`latency_ms` bigint NOT NULL DEFAULT 0,`finish_reason` varchar(50) NOT NULL DEFAULT '',`error_type` varchar(64) NOT NULL DEFAULT '',`error_code` varchar(128) NOT NULL DEFAULT '',`error_message` text,`created_at` datetime(3) NOT NULL,`updated_at` datetime(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `idx_conversation_turn_sequence` (`conversation_id`,`turn_sequence`),INDEX `idx_conversation_turn_created` (`conversation_id`,`created_at`),UNIQUE INDEX `idx_conversation_turns_call_id` (`call_id`),INDEX `idx_conversation_turns_request_log_id` (`request_log_id`),INDEX `idx_conversation_turns_model` (`model`),INDEX `idx_conversation_turns_provider_response_id` (`provider_response_id`),INDEX `idx_conversation_turns_status` (`status`),INDEX `idx_conversation_turns_error_code` (`error_code`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `conversation_items` (`id` bigint unsigned AUTO_INCREMENT,`conversation_id` bigint unsigned NOT NULL,`turn_id` bigint unsigned NOT NULL,`turn_sequence` bigint unsigned NOT NULL,`direction` varchar(16) NOT NULL,`ordinal` bigint NOT NULL,`canonical_json` JSON NOT NULL,`created_at` datetime(3) NOT NULL,PRIMARY KEY (`id`),INDEX `idx_conversation_items_order` (`conversation_id`,`turn_sequence`,`ordinal`),UNIQUE INDEX `idx_conversation_item_ordinal` (`turn_id`,`ordinal`),INDEX `idx_conversation_items_direction` (`direction`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `conversation_projection_outbox` (`call_id` varchar(64),`conversation_id` bigint unsigned NOT NULL DEFAULT 0,`previous_response_id` varchar(128) NOT NULL DEFAULT '',`request_log_id` bigint unsigned NOT NULL DEFAULT 0,`provider_response_id` varchar(128) NOT NULL DEFAULT '',`finish_reason` varchar(50) NOT NULL DEFAULT '',`input_json` longblob,`output_json` longblob,`input_ready` boolean NOT NULL DEFAULT false,`input_prepared` boolean NOT NULL DEFAULT false,`context_mode` varchar(24) NOT NULL DEFAULT '',`output_ready` boolean NOT NULL DEFAULT false,`retry_count` bigint NOT NULL DEFAULT 0,`last_error` text,`last_attempt_at` datetime(3) NULL,`next_attempt_at` datetime(3) NULL,`created_at` datetime(3) NOT NULL,`updated_at` datetime(3) NOT NULL,PRIMARY KEY (`call_id`),INDEX `idx_conversation_projection_conversation_id` (`conversation_id`),INDEX `idx_conversation_projection_previous_response_id` (`previous_response_id`),INDEX `idx_conversation_projection_request_log_id` (`request_log_id`),INDEX `idx_conversation_projection_retry` (`next_attempt_at`,`updated_at`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `billing_logs` (`id` bigint unsigned AUTO_INCREMENT COMMENT '主键ID',`created_at` datetime(3) NULL COMMENT '创建时间',`updated_at` datetime(3) NULL COMMENT '更新时间',`deleted_at` datetime(3) NULL COMMENT '删除时间',`idempotent_key` varchar(100) NOT NULL COMMENT '幂等键(如task_no)',`token_id` bigint unsigned COMMENT '令牌ID',`user_id` bigint unsigned COMMENT '用户ID',`call_id` varchar(64) NOT NULL DEFAULT '',`attempt_id` bigint unsigned NOT NULL DEFAULT 0,`phase` varchar(24) NOT NULL DEFAULT '',`pricing_snapshot` JSON,`amount` decimal(20,8) NOT NULL DEFAULT '0' COMMENT '金额',`type` varchar(10) NOT NULL COMMENT '类型(deduct/refund)',`status` varchar(10) DEFAULT 'success' COMMENT '状态',`remark` varchar(200) COMMENT '备注',PRIMARY KEY (`id`),INDEX `idx_billing_logs_created_at` (`created_at`),INDEX `idx_billing_logs_deleted_at` (`deleted_at`),UNIQUE INDEX `idx_billing_logs_idempotent_key` (`idempotent_key`),INDEX `idx_billing_logs_token_id` (`token_id`),INDEX `idx_billing_logs_user_id` (`user_id`),INDEX `idx_billing_logs_call_id` (`call_id`),INDEX `idx_billing_logs_attempt_id` (`attempt_id`),INDEX `idx_billing_logs_phase` (`phase`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `api_calls` (`id` varchar(64),`request_id` varchar(128) NOT NULL DEFAULT '',`user_id` bigint unsigned NOT NULL,`token_id` bigint unsigned NOT NULL,`endpoint` varchar(255) NOT NULL DEFAULT '',`operation` varchar(32) NOT NULL DEFAULT '',`model` varchar(80) NOT NULL DEFAULT '',`status` varchar(24) NOT NULL DEFAULT 'received',`is_stream` boolean NOT NULL DEFAULT false,`background` boolean NOT NULL DEFAULT false,`store` boolean NOT NULL DEFAULT false,`retain_payload` boolean NOT NULL DEFAULT false,`payload_expires_at` datetime(3) NULL,`resource_type` varchar(32) NOT NULL DEFAULT '',`resource_id` varchar(64) NOT NULL DEFAULT '',`conversation_id` bigint unsigned NOT NULL DEFAULT 0,`project_conversation` boolean NOT NULL DEFAULT false,`final_attempt_id` bigint unsigned NOT NULL DEFAULT 0,`attempt_count` bigint NOT NULL DEFAULT 0,`input_tokens` bigint NOT NULL DEFAULT 0,`output_tokens` bigint NOT NULL DEFAULT 0,`total_tokens` bigint NOT NULL DEFAULT 0,`cached_input_tokens` bigint NOT NULL DEFAULT 0,`reasoning_output_tokens` bigint NOT NULL DEFAULT 0,`usage_json` JSON,`reserved_amount` decimal(20,8) NOT NULL DEFAULT '0',`final_cost` decimal(20,8) NOT NULL DEFAULT '0',`refunded_amount` decimal(20,8) NOT NULL DEFAULT '0',`http_status` bigint NOT NULL DEFAULT 0,`error_type` varchar(64) NOT NULL DEFAULT '',`error_code` varchar(128) NOT NULL DEFAULT '',`error_message` text,`error_param` JSON,`error_retryable` boolean NOT NULL DEFAULT false,`started_at` datetime(3) NOT NULL,`first_byte_at` datetime(3) NULL,`completed_at` datetime(3) NULL,`duration_ms` bigint NOT NULL DEFAULT 0,`ttft_ms` bigint NOT NULL DEFAULT 0,`client_disconnected` boolean NOT NULL DEFAULT false,`lease_owner` varchar(64) NOT NULL DEFAULT '',`lease_expires_at` datetime(3) NULL,`created_at` datetime(3) NOT NULL,`updated_at` datetime(3) NOT NULL,PRIMARY KEY (`id`),INDEX `idx_api_calls_request_id` (`request_id`),INDEX `idx_api_calls_user_created` (`user_id`,`created_at`),INDEX `idx_api_calls_token_created` (`token_id`,`created_at`),INDEX `idx_api_calls_endpoint` (`endpoint`),INDEX `idx_api_calls_operation` (`operation`),INDEX `idx_api_calls_model` (`model`),INDEX `idx_api_calls_status_created` (`status`,`created_at`),INDEX `idx_api_calls_payload_expires_at` (`payload_expires_at`),INDEX `idx_api_calls_resource` (`resource_type`,`resource_id`),INDEX `idx_api_calls_conversation_id` (`conversation_id`),INDEX `idx_api_calls_final_attempt_id` (`final_attempt_id`),INDEX `idx_api_calls_error_code` (`error_code`),INDEX `idx_api_calls_started_at` (`started_at`),INDEX `idx_api_calls_lease_expires_at` (`lease_expires_at`),INDEX `idx_api_calls_created_at` (`created_at`),INDEX `idx_api_calls_updated_at` (`updated_at`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `api_call_attempts` (`id` bigint unsigned AUTO_INCREMENT,`call_id` varchar(64) NOT NULL,`attempt_no` bigint NOT NULL,`route_kind` varchar(24) NOT NULL DEFAULT 'gateway_v2',`stage` varchar(24) NOT NULL DEFAULT '',`ability_id` bigint unsigned NOT NULL DEFAULT 0,`channel_id` bigint unsigned NOT NULL DEFAULT 0,`key_id` bigint unsigned NOT NULL DEFAULT 0,`endpoint_id` bigint unsigned NOT NULL DEFAULT 0,`account_id` bigint unsigned NOT NULL DEFAULT 0,`protocol` varchar(20) NOT NULL DEFAULT '',`vendor_model` varchar(120) NOT NULL DEFAULT '',`transport` varchar(64) NOT NULL DEFAULT '',`request_path` varchar(255) NOT NULL DEFAULT '',`status` varchar(24) NOT NULL DEFAULT 'started',`http_status` bigint NOT NULL DEFAULT 0,`error_type` varchar(64) NOT NULL DEFAULT '',`error_code` varchar(128) NOT NULL DEFAULT '',`error_message` text,`error_retryable` boolean NOT NULL DEFAULT false,`input_tokens` bigint NOT NULL DEFAULT 0,`output_tokens` bigint NOT NULL DEFAULT 0,`total_tokens` bigint NOT NULL DEFAULT 0,`cached_input_tokens` bigint NOT NULL DEFAULT 0,`reasoning_output_tokens` bigint NOT NULL DEFAULT 0,`usage_json` JSON,`duration_ms` bigint NOT NULL DEFAULT 0,`ttft_ms` bigint NOT NULL DEFAULT 0,`provider_response_id` varchar(128) NOT NULL DEFAULT '',`started_at` datetime(3) NOT NULL,`first_byte_at` datetime(3) NULL,`completed_at` datetime(3) NULL,`created_at` datetime(3) NOT NULL,`updated_at` datetime(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `idx_api_call_attempt_no` (`call_id`,`attempt_no`),INDEX `idx_api_call_attempts_route_kind` (`route_kind`),INDEX `idx_api_call_attempts_stage` (`stage`),INDEX `idx_api_call_attempts_ability_id` (`ability_id`),INDEX `idx_api_call_attempts_channel_id` (`channel_id`),INDEX `idx_api_call_attempts_key_id` (`key_id`),INDEX `idx_api_call_attempts_endpoint_id` (`endpoint_id`),INDEX `idx_api_call_attempts_account_id` (`account_id`),INDEX `idx_api_call_attempts_transport` (`transport`),INDEX `idx_api_call_attempts_status` (`status`),INDEX `idx_api_call_attempts_error_code` (`error_code`),INDEX `idx_api_call_attempts_provider_response_id` (`provider_response_id`),INDEX `idx_api_call_attempts_started_at` (`started_at`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `api_call_payloads` (`id` bigint unsigned AUTO_INCREMENT,`call_id` varchar(64) NOT NULL,`attempt_id` bigint unsigned NOT NULL DEFAULT 0,`kind` varchar(32) NOT NULL,`content_type` varchar(128) NOT NULL DEFAULT 'application/json',`data` longblob,`encrypted` boolean NOT NULL DEFAULT false,`truncated` boolean NOT NULL DEFAULT false,`original_bytes` bigint NOT NULL DEFAULT 0,`expires_at` datetime(3) NULL,`created_at` datetime(3) NOT NULL,`updated_at` datetime(3) NOT NULL,PRIMARY KEY (`id`),INDEX `idx_api_call_payload_kind` (`call_id`,`kind`),INDEX `idx_api_call_payloads_attempt_id` (`attempt_id`),INDEX `idx_api_call_payloads_expires_at` (`expires_at`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `balance_entries` (`id` bigint unsigned AUTO_INCREMENT,`entry_key` varchar(100) NOT NULL,`source_key` varchar(128) NOT NULL DEFAULT '',`account_type` varchar(16) NOT NULL,`account_id` bigint unsigned NOT NULL,`user_id` bigint unsigned NOT NULL DEFAULT 0,`token_id` bigint unsigned NOT NULL DEFAULT 0,`direction` varchar(10) NOT NULL,`category` varchar(32) NOT NULL,`amount` decimal(20,8) NOT NULL,`balance_before` decimal(20,8) NOT NULL,`balance_after` decimal(20,8) NOT NULL,`call_id` varchar(64) NOT NULL DEFAULT '',`attempt_id` bigint unsigned NOT NULL DEFAULT 0,`actor_user_id` bigint unsigned NOT NULL DEFAULT 0,`metadata` JSON,`created_at` datetime(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `idx_balance_entries_entry_key` (`entry_key`),INDEX `idx_balance_entries_source_key` (`source_key`),INDEX `idx_balance_account_created` (`account_type`,`account_id`,`created_at`),INDEX `idx_balance_user_created` (`user_id`,`created_at`),INDEX `idx_balance_token_created` (`token_id`,`created_at`),INDEX `idx_balance_entries_direction` (`direction`),INDEX `idx_balance_entries_category` (`category`),INDEX `idx_balance_entries_call_id` (`call_id`),INDEX `idx_balance_entries_attempt_id` (`attempt_id`),INDEX `idx_balance_entries_actor_user_id` (`actor_user_id`),INDEX `idx_balance_entries_created_at` (`created_at`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `api_access_logs` (`id` bigint unsigned AUTO_INCREMENT,`request_id` varchar(128) NOT NULL DEFAULT '',`call_id` varchar(64) NOT NULL DEFAULT '',`user_id` bigint unsigned NOT NULL DEFAULT 0,`token_id` bigint unsigned NOT NULL DEFAULT 0,`actor_type` varchar(16) NOT NULL DEFAULT 'anonymous',`method` varchar(10) NOT NULL,`path` varchar(500) NOT NULL,`route` varchar(500) NOT NULL DEFAULT '',`query` text,`status_code` bigint NOT NULL DEFAULT 0,`duration_ms` bigint NOT NULL DEFAULT 0,`ip` varchar(64) NOT NULL DEFAULT '',`user_agent` varchar(512) NOT NULL DEFAULT '',`error_code` varchar(128) NOT NULL DEFAULT '',`created_at` datetime(3) NOT NULL,PRIMARY KEY (`id`),INDEX `idx_api_access_logs_request_id` (`request_id`),INDEX `idx_api_access_logs_call_id` (`call_id`),INDEX `idx_api_access_user_created` (`user_id`,`created_at`),INDEX `idx_api_access_token_created` (`token_id`,`created_at`),INDEX `idx_api_access_logs_actor_type` (`actor_type`),INDEX `idx_api_access_logs_method` (`method`),INDEX `idx_api_access_logs_route` (`route`),INDEX `idx_api_access_logs_status_code` (`status_code`),INDEX `idx_api_access_logs_error_code` (`error_code`),INDEX `idx_api_access_logs_created_at` (`created_at`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `audit_events` (`id` bigint unsigned AUTO_INCREMENT,`request_id` varchar(128) NOT NULL DEFAULT '',`actor_type` varchar(16) NOT NULL DEFAULT 'anonymous',`actor_user_id` bigint unsigned NOT NULL DEFAULT 0,`actor_token_id` bigint unsigned NOT NULL DEFAULT 0,`action` varchar(128) NOT NULL,`resource_type` varchar(64) NOT NULL DEFAULT '',`resource_id` varchar(128) NOT NULL DEFAULT '',`outcome` varchar(16) NOT NULL,`http_status` bigint NOT NULL DEFAULT 0,`ip` varchar(64) NOT NULL DEFAULT '',`metadata` JSON,`created_at` datetime(3) NOT NULL,PRIMARY KEY (`id`),INDEX `idx_audit_events_request_id` (`request_id`),INDEX `idx_audit_events_actor_type` (`actor_type`),INDEX `idx_audit_actor_created` (`actor_user_id`,`created_at`),INDEX `idx_audit_events_actor_token_id` (`actor_token_id`),INDEX `idx_audit_events_action` (`action`),INDEX `idx_audit_events_resource_type` (`resource_type`),INDEX `idx_audit_events_resource_id` (`resource_id`),INDEX `idx_audit_events_outcome` (`outcome`),INDEX `idx_audit_events_created_at` (`created_at`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `account_model_states` (`id` bigint unsigned AUTO_INCREMENT,`account_id` bigint unsigned NOT NULL COMMENT '账号ID',`model_code` varchar(80) NOT NULL COMMENT '模型标识',`disabled_until` datetime(3) NOT NULL COMMENT '熔断到期时间',`reason` varchar(500) DEFAULT '' COMMENT '熔断原因',`status_code` bigint DEFAULT 0 COMMENT '触发的HTTP状态码',`fail_count` bigint DEFAULT 1 COMMENT '累计触发次数',`created_at` datetime(3) NULL,`updated_at` datetime(3) NULL,PRIMARY KEY (`id`),UNIQUE INDEX `idx_account_model` (`account_id`,`model_code`),INDEX `idx_account_model_states_disabled_until` (`disabled_until`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `account_models` (`id` bigint unsigned AUTO_INCREMENT,`account_id` bigint unsigned NOT NULL COMMENT '账号(key)ID',`model_code` varchar(80) NOT NULL COMMENT '模型标识',`vendor_model` varchar(120) DEFAULT '' COMMENT '上游模型名(空=用model_code)',`priority` bigint DEFAULT 0 COMMENT '优先级(降序)',`status` tinyint DEFAULT 1 COMMENT '状态(1启用/0禁用)',`price_mode` varchar(10) DEFAULT 'token' COMMENT '计价模式',`input_price` decimal(12,8) DEFAULT '0' COMMENT '输入价格',`output_price` decimal(12,8) DEFAULT '0' COMMENT '输出价格',`created_at` datetime(3) NULL,`updated_at` datetime(3) NULL,PRIMARY KEY (`id`),UNIQUE INDEX `idx_am_account_model` (`account_id`,`model_code`),INDEX `idx_account_models_priority` (`priority`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `gw_channels` (`id` bigint unsigned AUTO_INCREMENT,`name` varchar(100) NOT NULL,`protocol` varchar(20) NOT NULL DEFAULT 'openai',`base_url` varchar(255) NOT NULL,`extra_headers` JSON,`config` JSON,`status` tinyint DEFAULT 1,`sort` bigint DEFAULT 0,`created_at` datetime(3) NULL,`updated_at` datetime(3) NULL,`deleted_at` datetime(3) NULL,PRIMARY KEY (`id`),INDEX `idx_gw_channels_sort` (`sort`),INDEX `idx_gw_channels_created_at` (`created_at`),INDEX `idx_gw_channels_deleted_at` (`deleted_at`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `gw_channel_keys` (`id` bigint unsigned AUTO_INCREMENT,`channel_id` bigint unsigned NOT NULL,`name` varchar(100),`api_key` text NOT NULL,`weight` bigint DEFAULT 10,`status` tinyint DEFAULT 1,`max_conc` bigint DEFAULT 0,`current_conc` bigint DEFAULT 0,`created_at` datetime(3) NULL,`updated_at` datetime(3) NULL,`deleted_at` datetime(3) NULL,PRIMARY KEY (`id`),INDEX `idx_gw_channel_keys_channel_id` (`channel_id`),INDEX `idx_gw_channel_keys_deleted_at` (`deleted_at`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `gw_abilities` (`id` bigint unsigned AUTO_INCREMENT,`model_name` varchar(80) NOT NULL,`channel_id` bigint unsigned NOT NULL,`key_id` bigint unsigned NOT NULL,`vendor_model` varchar(120) NOT NULL,`priority` bigint DEFAULT 0,`price_mode` varchar(10) DEFAULT 'token',`input_price` decimal(12,8) DEFAULT '0',`output_price` decimal(12,8) DEFAULT '0',`capabilities` JSON,`status` tinyint DEFAULT 1,`created_at` datetime(3) NULL,`updated_at` datetime(3) NULL,PRIMARY KEY (`id`),INDEX `idx_gw_ability_model` (`model_name`,`priority`,`status`),INDEX `idx_gw_abilities_key_id` (`key_id`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `gw_ability_transports` (`id` bigint unsigned AUTO_INCREMENT,`ability_id` bigint unsigned NOT NULL,`transport` varchar(64) NOT NULL,`status` tinyint NOT NULL DEFAULT 1,`config` JSON,`checked_at` datetime(3) NULL,`last_error` varchar(1000) DEFAULT '',`created_at` datetime(3) NULL,`updated_at` datetime(3) NULL,PRIMARY KEY (`id`),UNIQUE INDEX `idx_gw_ability_transport` (`ability_id`,`transport`),INDEX `idx_gw_ability_transport_status` (`ability_id`,`transport`,`status`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `gw_route_states` (`id` bigint unsigned AUTO_INCREMENT,`key_id` bigint unsigned NOT NULL,`model_name` varchar(80) NOT NULL,`transport` varchar(64) NOT NULL,`disabled_until` datetime(3) NOT NULL,`reason` varchar(500) DEFAULT '',`status_code` bigint DEFAULT 0,`fail_count` bigint DEFAULT 1,`created_at` datetime(3) NULL,`updated_at` datetime(3) NULL,PRIMARY KEY (`id`),UNIQUE INDEX `idx_gw_route_state` (`key_id`,`model_name`,`transport`),INDEX `idx_gw_route_states_key_id` (`key_id`),INDEX `idx_gw_route_states_disabled_until` (`disabled_until`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `gw_model_meta` (`model_name` varchar(80),`display_name` varchar(100),`thinking_config` JSON,`max_tokens` bigint DEFAULT 0,`features` JSON,`group_name` varchar(80) DEFAULT '',`status` tinyint DEFAULT 1,`sort` bigint DEFAULT 0,`updated_at` datetime(3) NULL,PRIMARY KEY (`model_name`),INDEX `idx_gw_model_meta_sort` (`sort`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `ai_responses` (`id` varchar(64),`user_id` bigint unsigned NOT NULL,`token_id` bigint unsigned NOT NULL,`call_id` varchar(64) NOT NULL DEFAULT '',`model` varchar(80) NOT NULL,`status` varchar(24) NOT NULL,`background` boolean DEFAULT false,`store` boolean DEFAULT true,`previous_response_id` varchar(64) NOT NULL DEFAULT '',`provider_response_id` varchar(128) NOT NULL DEFAULT '',`channel_id` bigint unsigned DEFAULT 0,`key_id` bigint unsigned DEFAULT 0,`upstream_transport` varchar(64) NOT NULL DEFAULT '',`request_log_id` bigint unsigned DEFAULT 0,`request_json` JSON,`request_hash` char(64) NOT NULL DEFAULT '',`lease_owner` varchar(64) NOT NULL DEFAULT '',`lease_expires_at` datetime(3) NULL,`execution_attempt` bigint NOT NULL DEFAULT 0,`result_ready_at` datetime(3) NULL,`input_items` JSON,`output_items` JSON,`response_json` JSON,`usage_json` JSON,`metadata` JSON,`error_json` JSON,`idempotency_key` varbinary(512) NOT NULL DEFAULT '',`created_at` datetime(3) NULL,`completed_at` datetime(3) NULL,PRIMARY KEY (`id`),INDEX `idx_ai_responses_user` (`user_id`),INDEX `idx_ai_responses_token` (`token_id`),UNIQUE INDEX `idx_ai_responses_idempotency` (`token_id`,`idempotency_key`),INDEX `idx_ai_responses_call` (`call_id`),INDEX `idx_ai_responses_model` (`model`),INDEX `idx_ai_responses_status` (`status`),INDEX `idx_ai_responses_previous` (`previous_response_id`),INDEX `idx_ai_responses_request_log` (`request_log_id`),INDEX `idx_ai_responses_lease` (`lease_expires_at`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `ai_response_idempotency_cache` (`token_id` bigint unsigned,`idempotency_key` varbinary(128),`request_hash` char(64) NOT NULL,`owner` varchar(64) NOT NULL DEFAULT '',`status` varchar(16) NOT NULL,`response_id` varchar(64) NOT NULL DEFAULT '',`response_json` JSON,`expires_at` datetime(3) NOT NULL,`created_at` datetime(3) NOT NULL,`updated_at` datetime(3) NOT NULL,PRIMARY KEY (`token_id`,`idempotency_key`),INDEX `idx_ai_response_idempotency_status` (`status`),INDEX `idx_ai_response_idempotency_expires` (`expires_at`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `ai_files` (`id` varchar(64),`user_id` bigint unsigned NOT NULL,`token_id` bigint unsigned NOT NULL,`filename` varchar(255) NOT NULL,`purpose` varchar(40) NOT NULL,`bytes` bigint NOT NULL,`mime_type` varchar(120) NOT NULL DEFAULT '',`content` longblob NOT NULL,`status` varchar(24) NOT NULL DEFAULT 'processed',`created_at` datetime(3) NULL,PRIMARY KEY (`id`),INDEX `idx_ai_files_user` (`user_id`),INDEX `idx_ai_files_token` (`token_id`),INDEX `idx_ai_files_purpose` (`purpose`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
